/// <summary>
/// Get HMIMItemMaterial Extension
/// </summary>
/// <returns>HMIMItemMaterial Extension</returns>
public METHMIMItemMaterial metHMIMItemMaterial()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METHMIMItemMaterial));
}

    /// <summary>
    /// pack HMIMItemMaterial Extension
    /// </summary>
    /// <param name = "_metHMIMItemMaterial">METHMIMItemMaterial to pack</param>
    public void metPackMETHMIMItemMaterial(METHMIMItemMaterial  _metHMIMItemMaterial)
    {
        _metHMIMItemMaterial.RefRecId = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metHMIMItemMaterial);
    }

    /// <summary>
    ///    Inserts a table buffer into the database.
    /// </summary>
    public void insert()
    {
        METHMIMItemMaterial     metHMIMItemMaterial;

        this.ClassCode = HMIMDivision::find(this.DivisionCode).ClassCode;

        next insert();

        metHMIMItemMaterial    =   this.metHMIMItemMaterial();
        if (!metHMIMItemMaterial.RecId)
        {
            this.metPackMETHMIMItemMaterial(metHMIMItemMaterial);
        }

        this.SysExtensionSerializerMap::postInsert();
    }

    /// <summary>
    ///    Updates a table buffer into the database.
    /// </summary>
    public void update()
    {
        METHMIMItemMaterial     metHMIMItemMaterial;

        this.ClassCode = HMIMDivision::find(this.DivisionCode).ClassCode;

        next update();

        metHMIMItemMaterial    =   this.metHMIMItemMaterial();
        
        this.metPackMETHMIMItemMaterial(metHMIMItemMaterial);        

        this.SysExtensionSerializerMap::postUpdate();
    }

    /// <summary>
    /// Update the class code when modify the division code.
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);  

        switch (_fieldId)
        {
            case fieldNum(HMIMItemMaterial, DivisionCode):
                    this.ClassCode = HMIMDivision::find(this.DivisionCode).ClassCode;
                break;

            default:
                break;
        }
    }
